import{_ as r,l as n,o as e,c as s,v as t,p as l,x as o,d,i as m,S as u}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"莫比乌斯反演","description":"","frontmatter":{"title":"莫比乌斯反演","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mobius-inversion.md","filePath":"cs/mobius-inversion.md","lastUpdated":1789023840000}'),p={name:"cs/mobius-inversion.md"};function c(h,a,f,_,b,g){const i=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="莫比乌斯反演" tabindex="-1">莫比乌斯反演 <a class="header-anchor" href="#莫比乌斯反演" aria-label="Permalink to &quot;莫比乌斯反演&quot;">​</a></h1><div class="epigraph"><p>若 $g(n)=\\sum_{d\\mid n}f(d)$，则 $f(n)=\\sum_{d\\mid n}\\mu(d)g(n/d)$；除数格上的卷积逆就是 $\\mu$。</p><footer>—— 据 Möbius；Apostol, Introduction to Analytic Number Theory；[欧拉函数与莫比乌斯](/cs/euler-mobius) 整理</footer></div><p>上一课<a href="/cs/generating-functions">生成函数</a>是 \\(n\\) 的加法卷积。数论里常用<strong>除数卷积</strong>。\\(\\varphi\\) 课已给 \\(\\mu\\) 与 \\(\\sum_{d\\mid n}\\mu(d)=[n=1]\\)。缺口是反演公式及其算法用：把「含倍数的计数」变成「恰好」的计数。不重写线性筛填 \\(\\mu\\)。后课期望 DP 换概率。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(g=f*\\mathbf{1}\\) 则 \\(f=g*\\mu\\)。典型：\\(g(n)\\) 为 \\(1..n\\) 中满足「\\(d\\mid\\gcd\\)」的对数，\\(f\\) 为 \\(\\gcd=k\\) 的个数。实现：枚举 \\(d\\mid n\\) 或整除分块（\\(\\lfloor n/i\\rfloor\\) 段相同）做前缀 \\(\\sum\\mu\\)、$ \\sum\\varphi$。杜教筛点名：用恒等式在亚线性求积性前缀。</p><p>缺口是反演，不是 \\(\\zeta(s)\\)。</p><h3 id="不是容斥的对立面" tabindex="-1">不是容斥的对立面 <a class="header-anchor" href="#不是容斥的对立面" aria-label="Permalink to &quot;不是容斥的对立面&quot;">​</a></h3><p>容斥是子集格的 \\(\\mu\\)；除数格是另一偏序。同一莫比乌斯函数在 \\(n\\) 的因子格上取值正好是数论 \\(\\mu\\)。点名 poset 即可，不写 Möbius 反演的范畴论。</p><p><span class="marginnote">Apostol 数论教科书。整除分块是算法课标准。后课期望 DP 用线性性，不靠 \\(\\mu\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先写清 \\(g\\) 与 \\(f\\) 的卷积关系，再乘 \\(\\mu\\)。需要 \\(1..n\\) 前缀则筛 \\(\\mu\\) 或杜教。单点枚举因子 \\(O(\\sqrt n)\\)。</p>',11)),(e(),l(u,null,{default:o(()=>[m(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22g%20%3D%20f%20*%201%22%5D%20--%3E%20INV%5B%22f%20%3D%20g%20*%20%CE%BC%22%5D%0A%20%20INV%20--%3E%20BLK%5B%22%E6%95%B4%E9%99%A4%E5%88%86%E5%9D%97%20%2F%20%E7%AD%9B%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>注意 \\(*\\) 是除数卷积不是生成函数乘。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>\\(\\mathbf{1}*\\mu=\\varepsilon\\) 单位 \\([n=1]\\)，故左乘 \\(\\mu\\) 可逆。与容斥：\\(|A\\cup B|=\\) 先加后减，符号即 \\(\\mu\\)。与 Lucas 无关。与 NTT：Dirichlet 卷积可用分治 FFT（DNTT 一类）点名，本课 \\(O(n\\log n)\\) 筛前缀已够许多题。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写杜教筛完整证明。不写格上一般 \\(\\mu\\)。后课默认：倍数计数 \\(\\leftrightarrow\\) \\(\\mu\\) 反演。下一课概率与期望 DP。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>除数卷积的逆是 \\(\\mu\\)。</li><li>把「整除条件」的求和换成精确 \\(f\\)。</li><li>与 OGF 卷积不是同一 \\(*\\)。</li><li>出处：Möbius；Apostol；\\(\\mu\\) 见 CLRS 第 31 章。</li></ul>',7))])}const D=r(p,[["render",c]]);export{A as __pageData,D as default};
